// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2008, "10-11", [{"author":"Б. Иомдин","question":"Вот фраза из повести Чингиза Айтматова «Белый пароход»: <em>— Да ты, никак, занемог, — огорчился дед.</em> А что означают слова деда?","choices":["‘ты никак не смог’","‘ты, похоже, не смог’","‘ты сильно заболел’","‘ты, похоже, заболел’","‘ты, кажется, онемел’."],"key":"Г","review":["Слова деда у Айтматова","Раздели фразу на «никак» и «занемог». Первое слово может передавать предположение, второе — начало болезни.","Дед говорит «ты, похоже, заболел». Здесь «никак» означает предположение, а «занемочь» — заболеть."]},{"author":"О. Шеманаева","question":"Какое из этих слов обычно не употребляют, говоря о человеческих волосах?","choices":["<em>грива</em>","<em>хвост</em>","<em>копна</em>","<em>крона</em>","<em>шапка</em>."],"key":"Г","review":["Названия причёсок","Подбери примеры: волосы бывают собраны в хвост, могут напоминать гриву или копну.","«Крона» обычно относится к ветвям дерева. Для человеческих волос употребляют «гриву», «хвост», «копну» и «шапку»."]},{"author":"О. Шеманаева","question":"Перед вами пять слов с пропусками. При этом во всех словах, кроме одного, пропущено одно и то же. В каком слове пропущено не то, что в остальных?","choices":["<em>дура...кий</em>","<em>рыболове...кий</em>","<em>залихва...кий</em>","<em>тка...кий</em>","<em>замоскворе...кий</em>."],"key":"В","review":["Согласные перед «-кий»","Восстанови все прилагательные, особенно формы от «ткач» и «залихват».","Пишутся «дурацкий», «рыболовецкий», «ткацкий» и «замоскворецкий» с «ц». В «залихватский» нужны две буквы «тс»."]},{"author":"Б. Иомдин","question":"<em>Есть печенья, нет…</em>:","choices":["<em>печеньев</em>","<em>печений</em>","<em>печеней</em>","<em>печень</em>","<em>печениев</em>."],"key":"Б","review":["Родительный множественного","Нужна форма от «печенье» во множественном числе. Сравни «нет варений» и «нет солений».","Нормативный родительный множественного — «печений». Например, «в продаже несколько видов печений»."]},{"author":"К. Кноп","question":"Какое слово пропущено в поговорке «<em>Мал ..., да дорог</em>»?","choices":["<em>капитал</em>","<em>Ямал</em>","<em>золотник</em>","<em>микроскоп</em>","<em>бизнес</em>."],"key":"В","review":["Недостающая часть поговорки","Ищи старое название небольшой меры веса. Поговорка говорит о чём-то маленьком, но ценном.","Говорят «Мал золотник, да дорог». Золотник — старая мера веса."]},{"author":"И. Иткин","question":"Даны пары глаголов: 1) <em>гореть — огреть</em>; 2) <em>отгореть — отогреть</em>; 3) <em>отгоревать — отогревать</em>. В каких парах представлены глаголы разного вида?","choices":["только в 1","только в 3","в 1 и 2","в 1 и 3","во всех."],"key":"Г","review":["Вид в трёх парах","Задай к каждому глаголу вопрос «что делать?» или «что сделать?». Не опирайся только на одинаковый видимый фрагмент корня.","«Гореть» и «отогревать» несовершенного вида. «Огреть» и «отгоревать» совершенного. В паре 2 оба глагола совершенного вида. Выделяются пары 1 и 3."]},{"author":"Б. Иомдин","question":"Как правильно?","choices":["<em>хрусталь, хрустальный, кристал, кристальный</em>","<em>хрусталь, хрустальный, кристалл, кристалльный</em>","<em>хрусталь, хрустальный, кристалл, кристальный</em>","<em>хрусталь, хрусталльный, кристалл, кристальный</em>","<em>хрусталль, хрусталльный, кристалл, кристалльный</em>."],"key":"В","review":["Согласные в родственных словах","Проверь написание существительных и отдельно прилагательных. Удвоение в основе может не сохраниться.","Пишут «хрусталь, хрустальный» с одной «л». В «кристалл» две «л», в «кристальный» одна."]},{"author":"Н. Валеева","question":"В каком из данных ниже предложений имеется обстоятельство цели?","choices":["<em>Иван приехал в Москву по железной дороге.</em>","<em>Иван приехал в Москву по прошествии года.</em>","<em>Иван приехал в Москву по делам.</em>","<em>Иван приехал в Москву по подложному паспорту.</em>","<em>Иван приехал в Москву, по слухам.</em>"],"key":"В","review":["Цель поездки","К каждому обороту задай вопрос: «как?», «спустя какое время?», «с какой целью?», «на каком основании?».","«По делам» отвечает на «зачем приехал?». Оно сообщает, что целью были дела в Москве."]},{"author":"Б. Иомдин","question":"Судья Демьян Демьянович разбирал спор и говорит: «Давайте <em>апеллировать фактами</em>». Иван Иванович исправил его: «Надо говорить <em>оперировать фактами</em>». Иван Никифорович не согласился: «Надо говорить <em>апеллировать к фактам</em>». Кто из троих выразился правильно?","choices":["только Демьян Демьянович","только Иван Иванович","только Иван Никифорович","Иван Иванович и Иван Никифорович","все трое."],"key":"Г","review":["Управление двух глаголов","Сравни вопросы «оперировать чем?» и «апеллировать к чему?». Посмотри, кто употребил подходящую конструкцию.","Нормальны «оперировать фактами» и «апеллировать к фактам». Правильно выразились Иван Иванович и Иван Никифорович."]},{"author":"Б. Иомдин","question":"В каком из этих слов есть приставка?","choices":["<em>стремиться</em>","<em>стреножить</em>","<em>строгать</em>","<em>строиться</em>","<em>струиться.</em>"],"key":"Б","review":["Начальная буква и приставка","Проверь, можно ли убрать первую «с» и получить связанное слово. Ищи действие с треногой или стягиванием ног.","«Стреножить» связано с «треножить», связывать ноги. Начальное «с-» здесь приставка, в остальных словах она не выделяется."]},{"author":"О. Шеманаева","question":"Про кого говорят «<em>аршин проглотил</em>»?","choices":["про зазнавшегося человека","про человека, который держится неестественно прямо","про человека, который все время молчит","про очень толстого человека","про человека, сведущего в каком-либо вопросе."],"key":"Б","review":["Образ в выражении","Аршин был мерой длины и названием длинной прямой мерки. Представь, какую осанку предполагает такая шутка.","«Аршин проглотил» говорят о человеке, который держится неестественно прямо и скованно."]},{"author":"Н. Валеева","question":"Какое из этих слов в современном литературном языке по признаку рода отличается от остальных?","choices":["<em>тревоги</em>","<em>заботы</em>","<em>хлопоты</em>","<em>проблемы</em>","<em>трудности</em>."],"key":"В","review":["Род и множественное число","Попробуй восстановить форму на «одна»: тревога, забота, проблема, трудность. У какого слова такой формы нет?","«Хлопоты» употребляются только во множественном числе, у них нет рода. Остальные существительные — женского рода."]},{"author":"Н. Валеева","question":"Какое из этих слов не означает действия, направленного на себя?","choices":["<em>самоанализ</em>","<em>самокритика</em>","<em>самообман</em>","<em>самоотвод</em>","<em>самоуправство</em>."],"key":"Д","review":["Значение части «само»","Определи, на кого направлено действие. Для «самоуправство» проверь, связано ли слово с личной инициативой или действием над собой.","«Самоуправство» — самовольное поведение, действие по собственному усмотрению. Эта часть слова описывает способ действия. В других примерах действие направлено на самого себя."]},{"author":"Я. Елисеева","question":"«Успение» — христианский праздник в память о кончине Богородицы. Слово <em>успение</em> — однокоренное со словом:","choices":["<em>успеть</em>","<em>сон</em>","<em>спелый</em>","<em>успех</em>","<em>пена</em>."],"key":"Б","review":["История слова о празднике","Вспомни старое «уснуть» и церковный образ смерти как сна. Сравни разные формы корня.","«Успение» означает засыпание, в этом контексте смерть. Исторически оно родственно «сну» и «спать»."]},{"author":"О. Шеманаева","question":"Даны названия четырёх стран и одного города: <em>Нидерланды, Кот-д’Ивуар, Сьерра-Леоне, Сальвадор, Рио-де-Жанейро</em> — и их буквальные переводы на русский язык (в перепутанном порядке): <em>берег слоновой кости, львиные горы, нижние земли, январская река, спаситель</em>. Как надо расположить названия, чтобы они шли в том же порядке, что и их переводы?","choices":["<em>Рио-де-Жанейро, Нидерланды, Сьерра-Леоне, Сальвадор, Кот-д’Ивуар</em>","<em>Рио-де-Жанейро, Сьерра-Леоне, Нидерланды, Сальвадор, Кот-д’Ивуар</em>","<em>Рио-де-Жанейро, Сальвадор, Нидерланды, Кот-д’Ивуар, Сьерра-Леоне</em>","<em>Кот-д’Ивуар, Сьерра-Леоне, Нидерланды, Рио-де-Жанейро, Сальвадор</em>","<em>Кот-д’Ивуар, Рио-де-Жанейро, Нидерланды, Сьерра-Леоне, Сальвадор</em>."],"key":"Г","review":["Перевод названий","Сопоставь «Кот» с французским словом о береге, а «Рио» — с романским словом о реке. Затем проверь остальные названия.","Кот-д’Ивуар — берег слоновой кости, Сьерра-Леоне — львиные горы, Нидерланды — нижние земли, Рио-де-Жанейро — январская река, Сальвадор — спаситель."]},{"author":"А. Лифшиц и О. Шеманаева","question":"Что можно и <em>дать</em>, и <em>взять</em>, не меняя смысла предложения?","choices":["клятву","расписку","обещание","обязательство","слово."],"key":"Г","review":["Два глагола об одном действии","Добавь к каждому существительному «дать» и «взять». Проверь, может ли в обоих случаях человек сам принять на себя ответственность.","«Дать обязательство» значит обязаться. «Взять обязательство» в смысле «взять на себя» выражает тот же поступок."]},{"author":"Н. Валеева","question":"Какое из данных предложений не является сложноподчинённым?","choices":["<em>Я так рад, что смог принять участие в конкурсе!</em>","<em>Вася так устал, что заснул мгновенно.</em>","<em>Уже так поздно, что же ты не спишь?</em>","<em>Я так и не решил, что же ему подарить.</em>","<em>Где та книга, что лежала на столе?</em>"],"key":"В","review":["Два употребления «что»","Проверь, где «что» присоединяет зависимую часть, а где само задаёт вопрос со значением «почему».","В «Уже так поздно, что же ты не спишь?» слова «что же» означают «почему же». Здесь две самостоятельные части, поэтому предложение не сложноподчинённое."]},{"author":"Н. Валеева","question":"1) <em>точь(в)точь</em>; 2) <em>точка(в)точку</em>; 3) <em>тютелька(в)тютельку</em>; 4) <em>один(в)один</em>. Раскройте скобки. В каких случаях следует выбрать раздельное написание?","choices":["во всех","во всех, кроме 1","во всех, кроме 2","в 3 и 4","в 2 и 4."],"key":"Б","review":["Написание устойчивых оборотов","Сверь написание каждого оборота со словарным. Один из них состоит из повторяющегося «точь» и пишется по особому образцу.","Пишут «точь-в-точь» через дефисы. Остальные сочетания раздельны: «точка в точку», «тютелька в тютельку», «один в один»."]},{"author":"И. Иткин и А. Никулин","question":"Македонский язык — один из славянских языков. Даны македонские слова с проставленным ударением и их переводы на русский язык:\n<em>бо́г</em> ‘бог’ — <em>по́лубог</em> ‘полубог’\n<em>ви́стина</em> ‘правда, истина’ — <em>полуви́стина</em> ‘полуправда’\n<em>жи́в</em> ‘живой’ — <em>по́лужив</em> ‘полуживой’\n<em>ме́сец</em> ‘месяц’ — <em>полуме́сец</em> ‘полумесяц’\n<em>мра́к</em> ‘мрак’ — <em>по́лумрак</em> ‘полумрак’\n<em>се́стра</em> ‘сестра’ — <em>полусе́стра</em> ‘сводная сестра’.\nКак правильно поставить ударение в македонских словах <em>полубрат</em> ‘сводный брат’ и <em>полуостров</em> ‘полуостров’, образованных от <em>бра́т</em> ‘брат’ и <em>о́стров</em> ‘остров’?","choices":["<em>полубра́т, полуо́стров</em>","<em>полу́брат, по́луостров</em>","<em>по́лубрат, полуо́стров</em>","<em>полубра́т, полуостро́в</em>","<em>по́лубрат, по́луостров</em>."],"key":"В","review":["Ударение по-македонски","Раздели основы после «полу-» по числу слогов. Отдельно сравни «бог», «жив», «мрак» и более длинные слова.","Односложная основа даёт ударение на первом слоге «по́лу-», поэтому «по́лубрат». В многосложной основе сохраняется её ударение: «полуо́стров»."]},{"author":"Н. Валеева","question":"Какую из этих фраз можно понять не так, как остальные?","choices":["<em>Лене доводилось засиживаться за работой допоздна.</em>","<em>Лене случалось засиживаться за работой допоздна.</em>","<em>Лене приходилось засиживаться за работой допоздна.</em>","<em>Лена, случалось, засиживалась за работой допоздна.</em>","<em>Лена порой засиживалась за работой допоздна.</em>"],"key":"В","review":["Случай или необходимость","Проверь, передаёт ли фраза повторение время от времени или иногда может означать обязанность.","«Приходилось засиживаться» может означать, что работа вынуждала Лену задерживаться. Остальные фразы сообщают только, что это иногда случалось."]},{"author":"И. Иткин","question":"Какое слово изменяется по числам?","choices":["<em>на</em> (частица)","<em>на</em> (предлог)","<em>не</em>","<em>ни</em>","<em>но</em>."],"key":"А","review":["Слово при передаче предмета","Вообрази, что даёшь предмет одному человеку, а затем нескольким. Меняется ли короткая реплика?","Одному можно сказать «на!», нескольким или вежливо одному — «нате!». У частицы «на» различаются формы числа."]},{"author":"О. Шеманаева","question":"Какое из этих слов не может быть несогласованным определением?","choices":["<em>люкс</em>","<em>класс</em>","<em>пик</em>","<em>хаки</em>","<em>барокко</em>."],"key":"Б","review":["Определение после названия","Вставь слова в сочетания вроде «номер люкс» и «цвет хаки». Ищи слово, которому для такой связи нужна иная падежная форма.","«Люкс», «пик», «хаки» и «барокко» могут следовать за существительным в данной форме. Для «класс» нужно, например, «вагон первого класса», где сама форма изменена."]},{"author":"Б. Иомдин","question":"Какой глагол истолкован во многих словарях через свою анаграмму, т. е. слово, получающееся из данного перестановкой букв?","choices":["<em>позариться</em>","<em>манежиться</em>","<em>переламывать</em>","<em>пробурить</em>","<em>разгореться</em>."],"key":"Б","review":["Перестановка букв в словаре","Подбери синонимы предложенным глаголам. Для одного получится переставить буквы исходного слова без остатка.","«Манежиться» толкуют через «жеманиться». В этих словах одни и те же буквы в разном порядке."]},{"author":"Н. Валеева","question":"В каком из данных ниже предложений сказуемое — простое глагольное?","choices":["<em>Маша пыталась его увидеть.</em>","<em>Маша рада была с ним поговорить.</em>","<em>Маша не смогла до него дозвониться.</em>","<em>Маша перестала о нём думать.</em>","<em>Маша не позволила ему приходить.</em>"],"key":"Д","review":["Кто должен действовать","Сопоставь подлежащее с тем, кто выполняет действие инфинитива. Если это разные люди, инфинитив не входит в сказуемое первого.","В «Маша не позволила ему приходить» приходить должен другой человек. «Не позволила» — простое глагольное сказуемое, «приходить» — зависимый инфинитив."]},{"author":"Н. Валеева","question":"Какая латинская буква должна занять следующее место в ряду I, V, X, L, ...?","choices":["C","D","M","N","S."],"key":"А","review":["Ряд латинских букв","Вспомни римские цифры. Запиши, какие числа обозначают четыре данные буквы.","«I» — 1, «V» — 5, «X» — 10, «L» — 50. Следующий знак в этом ряду — «C» для 100."]},{"author":"А. Бердичевский","question":"В начале прошлого века поэты, собиравшиеся в одном петербургском кафе, придумали стихотворную форму «боранаут». Перед вами фрагмент «боранаута» современного автора В. Бейлиса:\n<em>Раз Боранаут на Франкфуртский берег проветриться вышел.\nСтрасти сказал он: тубо! рана утраты болит.\nПосле отправился в (...), а наутро, страдая, усталый,\nБога моля, у собора на утрене стал.</em>\nВосстановите пропущенное слово.","choices":["<em>бар</em>","<em>бой</em>","<em>бор</em>","<em>сад</em>","<em>путь</em>."],"key":"В","review":["Повтор букв в строках","Прочти строки без пробелов и знаков. Ищи «боранаут», в том числе на стыке слов.","Во второй строке есть «тубо! рана утраты», в четвёртой — «собора на утрене». В третьей нужно «бор, а наутро», тогда те же буквы идут подряд."]},{"author":"К. Кноп","question":"Русская пословица «<em>Ужин хорош, да плох умолот</em>» говорит о том, что","choices":["много еды, но есть не хочется","обильно есть на ночь вредно","колосьев много, а зёрен мало","зерна много, а есть нечего","чужое брать без спроса нехорошо."],"key":"В","review":["Значение сельской пословицы","Сопоставь «ужин» со словом «жать», а «умолот» — с «молотить», отделяя зерно от соломы.","В пословице «ужин» — количество сжатого хлеба, «умолот» — полученное зерно. Колосьев много, а зёрен после обмолота мало."]},{"author":"Н. Валеева","question":"Даны слова <em>кладезь, прорубь и ставень</em>. Какие из них относятся к мужскому роду?","choices":["<em>кладезь</em> и <em>прорубь</em>","<em>кладезь</em> и <em>ставень</em>","<em>прорубь</em> и <em>ставень</em>","только <em>ставень</em>","только <em>кладезь</em>."],"key":"Б","review":["Род трёх существительных","Подставь «этот» или «эта». Все три слова заканчиваются на мягкий знак, но могут иметь разный род.","«Кладезь» и «ставень» — мужского рода. «Прорубь» — женского."]},{"author":"И. Иткин","question":"Даны названия профессий: <em>гончар, кочегар, маляр, токарь</em>. Какие из них в ходе истории русского языка утратили звук [р]?","choices":["<em>гончар</em> и <em>кочегар</em>","<em>гончар</em> и <em>маляр</em>","<em>кочегар</em> и <em>маляр</em>","<em>кочегар</em> и <em>токарь</em>","<em>маляр</em> и <em>токарь</em>."],"key":"А","review":["Согласный в названиях","Сравни профессии со словами «горн» и «кочерга». Ищи исчезнувшее историческое «р» внутри слова.","«Гончар» восходит к форме «горнчар». «Кочегар» восходит к «кочергарь», связанному с «кочерга». В обоих словах исчезло раннее «р»."]},{"author":"И. Иткин и А. Либер","question":"Русский писатель XIX века Титов писал под псевдонимом <em>Тит Космократов</em>. А как было его настоящее имя?","choices":["<em>Александр</em>","<em>Владимир</em>","<em>Кузьма</em>","<em>Демьян</em>","<em>Константин</em>."],"key":"Б","review":["Имя за псевдонимом","Разбери «Космократов»: первая часть напоминает греческое название мира, вторая связана с властью.","«Космократ» — владыка мира. «Владимир» здесь читается как «владеющий миром». Эту же мысль передаёт псевдоним Владимира Титова."]}], {"year":2008,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2008.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
